var STORAGE_KEY = "packs.v1";
function createPackRegistry(storage, initialOwned = null) {
  const catalogMap = new Map(PACK_CATALOG.map((p) => [p.id, p]));
  const saved = storage?.get ? storage.get(STORAGE_KEY, null) : null;
  const owned = new Set(
    Array.isArray(initialOwned) ? initialOwned : Array.isArray(saved?.owned) ? saved.owned : ["core_commons"]
  );
  owned.add("core_commons");
  const enabled = new Set(
    Array.isArray(saved?.enabled) ? saved.enabled.filter((id) => owned.has(id)) : ["core_commons"]
  );
  enabled.add("core_commons");
  let activeSeason = typeof saved?.activeSeason === "string" && catalogMap.get(saved.activeSeason)?.kind === PACK_KIND.SEASONAL ? saved.activeSeason : null;
  function persist() {
    storage?.set?.(STORAGE_KEY, {
      owned: [...owned],
      enabled: [...enabled],
      activeSeason
    });
  }
  return {
    listCatalog() {
      return PACK_CATALOG.map((p) => ({
        ...p,
        owned: owned.has(p.id),
        enabled: p.kind === PACK_KIND.SEASONAL ? activeSeason === p.id : enabled.has(p.id)
      }));
    },
    isSectorUnlocked(sectorId) {
      for (const pack of PACK_CATALOG) {
        if (pack.sectors.includes(sectorId)) {
          return owned.has(pack.id) && enabled.has(pack.id);
        }
      }
      return false;
    },
    unlockPack(packId) {
      if (!catalogMap.has(packId)) return false;
      owned.add(packId);
      const pack = catalogMap.get(packId);
      if (pack.kind === PACK_KIND.SEASONAL) {
        activeSeason = packId;
      } else {
        enabled.add(packId);
      }
      persist();
      return true;
    },
    setPackEnabled(packId, isOn) {
      const pack = catalogMap.get(packId);
      if (!pack || !owned.has(packId)) return false;
      if (pack.kind === PACK_KIND.CORE) return true;
      if (pack.kind === PACK_KIND.SEASONAL) {
        activeSeason = isOn ? packId : activeSeason === packId ? null : activeSeason;
      } else if (isOn) {
        enabled.add(packId);
      } else {
        enabled.delete(packId);
      }
      persist();
      return true;
    },
    getActiveSeason() {
      return activeSeason;
    },
    getSnapshot() {
      return {
        owned: [...owned],
        enabled: [...enabled],
        activeSeason
      };
    }
  };
}

